CONTRIBUTORS_EMAILS_DIR = REPO_ROOT / 'contributors' / 'emails'

def _load_contributor_dir(directory: 'Path | None'=None) -> dict:
    """Load one-file-per-email mappings from contributors/emails/.

    Filename = commit-author email, first non-comment line = GitHub login.
    Additions never merge-conflict (each mapping is a distinct file), which
    is why new entries go here instead of the frozen LEGACY_AUTHOR_MAP.
    """
    directory = directory or CONTRIBUTORS_EMAILS_DIR
    mapping = {}
    if not directory.is_dir():
        return mapping
    for path in sorted(directory.iterdir()):
        if not path.is_file() or path.name.startswith('.'):
            continue
        try:
            for line in path.read_text(encoding='utf-8').splitlines():
                line = line.strip()
                if line and (not line.startswith('#')):
                    mapping[path.name] = line.lstrip('@')
                    break
        except OSError:
            continue
    return mapping
AUTHOR_MAP = {**LEGACY_AUTHOR_MAP, **_load_contributor_dir()}

def git(*args, cwd=None):
    """Run a git command and return stdout."""
    result = subprocess.run(['git'] + list(args), capture_output=True, text=True, encoding='utf-8', errors='replace', cwd=cwd or str(REPO_ROOT))
    if result.returncode != 0:
        print(f"git {' '.join(args)} failed: {result.stderr}", file=sys.stderr)
        return ''
    return result.stdout.strip()

def git_result(*args, cwd=None):
    """Run a git command and return the full CompletedProcess."""
    return subprocess.run(['git'] + list(args), capture_output=True, text=True, encoding='utf-8', errors='replace', cwd=cwd or str(REPO_ROOT))

def get_last_tag():
    """Get the most recent CalVer tag."""
    tags = git('tag', '--list', 'v20*', '--sort=-v:refname')
    if tags:
        return tags.split('\n')[0]
    return None

def next_available_tag(base_tag: str) -> tuple[str, str]:
    """Return a tag/calver pair, suffixing same-day releases when needed."""
    if not git('tag', '--list', base_tag):
        return (base_tag, base_tag.removeprefix('v'))
    suffix = 2
    while git('tag', '--list', f'{base_tag}.{suffix}'):
        suffix += 1
    tag_name = f'{base_tag}.{suffix}'
    return (tag_name, tag_name.removeprefix('v'))

def get_current_version():
    """Read current semver from __init__.py."""
    content = VERSION_FILE.read_text(encoding='utf-8')
    match = re.search('__version__\\s*=\\s*"([^"]+)"', content)
    return match.group(1) if match else '0.0.0'

def bump_version(current: str, part: str) -> str:
    """Bump a semver version string."""
    parts = current.split('.')
    if len(parts) != 3:
        parts = ['0', '0', '0']
    major, minor, patch = (int(parts[0]), int(parts[1]), int(parts[2]))
    if part == 'major':
        major += 1
        minor = 0
        patch = 0
    elif part == 'minor':
        minor += 1
        patch = 0
    elif part == 'patch':
        patch += 1
    else:
        raise ValueError(f'Unknown bump part: {part}')
    return f'{major}.{minor}.{patch}'

def update_version_files(semver: str, calver_date: str):
    """Update version strings in source files."""
    content = VERSION_FILE.read_text(encoding='utf-8')
    content = re.sub('__version__\\s*=\\s*"[^"]+"', f'__version__ = "{semver}"', content)
    content = re.sub('__release_date__\\s*=\\s*"[^"]+"', f'__release_date__ = "{calver_date}"', content)
    VERSION_FILE.write_text(content, encoding='utf-8')
    pyproject = PYPROJECT_FILE.read_text(encoding='utf-8')
    pyproject = re.sub('^version\\s*=\\s*"[^"]+"', f'version = "{semver}"', pyproject, flags=re.MULTILINE)
    PYPROJECT_FILE.write_text(pyproject, encoding='utf-8')
    desktop_pkg = REPO_ROOT / 'apps' / 'desktop' / 'package.json'
    if desktop_pkg.exists():
        pkg_text = desktop_pkg.read_text(encoding='utf-8')
        pkg_text = re.sub('("version"\\s*:\\s*)"[^"]+"', f'\\g<1>"{semver}"', pkg_text, count=1)
        desktop_pkg.write_text(pkg_text, encoding='utf-8')

def resolve_author(name: str, email: str) -> str:
    """Resolve a git author to a GitHub @mention."""
    gh_user = AUTHOR_MAP.get(email)
    if gh_user:
        return f'@{gh_user}'
    noreply_match = re.match('(\\d+)\\+(.+)@users\\.noreply\\.github\\.com', email)
    if noreply_match:
        return f'@{noreply_match.group(2)}'
    noreply_match2 = re.match('(.+)@users\\.noreply\\.github\\.com', email)
    if noreply_match2:
        return f'@{noreply_match2.group(1)}'
    return name

def categorize_commit(subject: str) -> str:
    """Categorize a commit by its conventional commit prefix."""
    subject_lower = subject.lower()
    patterns = {'breaking': ['^breaking[\\s:(]', '^!:', 'BREAKING CHANGE'], 'features': ['^feat[\\s:(]', '^feature[\\s:(]', '^add[\\s:(]'], 'fixes': ['^fix[\\s:(]', '^bugfix[\\s:(]', '^bug[\\s:(]', '^hotfix[\\s:(]'], 'improvements': ['^improve[\\s:(]', '^perf[\\s:(]', '^enhance[\\s:(]', '^refactor[\\s:(]', '^cleanup[\\s:(]', '^clean[\\s:(]', '^update[\\s:(]', '^optimize[\\s:(]'], 'docs': ['^doc[\\s:(]', '^docs[\\s:(]'], 'tests': ['^test[\\s:(]', '^tests[\\s:(]'], 'chore': ['^chore[\\s:(]', '^ci[\\s:(]', '^build[\\s:(]', '^deps[\\s:(]', '^bump[\\s:(]']}
    for category, regexes in patterns.items():
        for regex in regexes:
            if re.match(regex, subject_lower):
                return category
    if any((w in subject_lower for w in ['add ', 'new ', 'implement', 'support '])):
        return 'features'
    if any((w in subject_lower for w in ['fix ', 'fixed ', 'resolve', 'patch '])):
        return 'fixes'
    if any((w in subject_lower for w in ['refactor', 'cleanup', 'improve', 'update '])):
        return 'improvements'
    return 'other'

def clean_subject(subject: str) -> str:
    """Clean up a commit subject for display."""
    cleaned = re.sub('^(feat|fix|docs|chore|refactor|test|perf|ci|build|improve|add|update|cleanup|hotfix|breaking|enhance|optimize|bugfix|bug|feature|tests|deps|bump)[\\s:(!]+\\s*', '', subject, flags=re.IGNORECASE)
    cleaned = cleaned.strip()
    if cleaned:
        cleaned = cleaned[0].upper() + cleaned[1:]
    return cleaned

def parse_coauthors(body: str) -> list:
    """Extract Co-authored-by trailers from a commit message body.

    Returns a list of {'name': ..., 'email': ...} dicts.
    Filters out AI assistants and bots (Claude, Copilot, Cursor, etc.).
    """
    if not body:
        return []
    _ignored_emails = {'noreply@anthropic.com', 'noreply@github.com', 'cursoragent@cursor.com', 'duck-agent@nousresearch.com'}
    _ignored_names = re.compile('^(Claude|Copilot|Cursor Agent|GitHub Actions?|dependabot|renovate)', re.IGNORECASE)
    pattern = re.compile('Co-authored-by:\\s*(.+?)\\s*<([^>]+)>', re.IGNORECASE)
    results = []
    for m in pattern.finditer(body):
        name, email = (m.group(1).strip(), m.group(2).strip())
        if email in _ignored_emails or _ignored_names.match(name):
            continue
        results.append({'name': name, 'email': email})
    return results

def get_commits(since_tag=None):
    """Get commits since a tag (or all commits if None)."""
    if since_tag:
        range_spec = f'{since_tag}..HEAD'
    else:
        range_spec = 'HEAD'
    log = git('log', range_spec, '--format=%H%x1f%an%x1f%ae%x1f%s%x00%b%x00', '--no-merges')
    if not log:
        return []
    commits = []
    for entry in log.split('\x00\x00'):
        entry = entry.strip()
        if not entry:
            continue
        if '\x00' in entry:
            header, body = entry.split('\x00', 1)
            body = body.strip()
        else:
            header = entry
            body = ''
        parts = header.split('\x1f', 3)
        if len(parts) != 4:
            continue
        sha, name, email, subject = parts
        coauthor_info = parse_coauthors(body)
        coauthors = [resolve_author(ca['name'], ca['email']) for ca in coauthor_info]
        commits.append({'sha': sha, 'short_sha': sha[:8], 'author_name': name, 'author_email': email, 'subject': subject, 'category': categorize_commit(subject), 'github_author': resolve_author(name, email), 'coauthors': coauthors})
    return commits

def get_pr_number(subject: str) -> str | None:
    """Extract PR number from commit subject if present."""
    match = re.search('#(\\d+)', subject)
    if match:
        return match.group(1)
    return None

def generate_changelog(commits, tag_name, semver, repo_url='https://github.com/NousResearch/duck-agent', prev_tag=None, first_release=False):
    """Generate markdown changelog from categorized commits."""
    lines = []
    now = datetime.now()
    date_str = now.strftime('%B %d, %Y')
    lines.append(f'# Duck Agent v{semver} ({tag_name})')
    lines.append('')
    lines.append(f'**Release Date:** {date_str}')
    lines.append('')
    if first_release:
        lines.append('> 🎉 **First official release!** This marks the beginning of regular weekly releases')
        lines.append('> for Duck Agent. See below for everything included in this initial release.')
        lines.append('')
    categories = defaultdict(list)
    all_authors = set()
    teknium_aliases = {'@teknium1'}
    for commit in commits:
        categories[commit['category']].append(commit)
        author = commit['github_author']
        if author not in teknium_aliases:
            all_authors.add(author)
        for coauthor in commit.get('coauthors', []):
            if coauthor not in teknium_aliases:
                all_authors.add(coauthor)
    category_order = [('breaking', '⚠️ Breaking Changes'), ('features', '✨ Features'), ('improvements', '🔧 Improvements'), ('fixes', '🐛 Bug Fixes'), ('docs', '📚 Documentation'), ('tests', '🧪 Tests'), ('chore', '🏗️ Infrastructure'), ('other', '📦 Other Changes')]
    for cat_key, cat_title in category_order:
        cat_commits = categories.get(cat_key, [])
        if not cat_commits:
            continue
        lines.append(f'## {cat_title}')
        lines.append('')
        for commit in cat_commits:
            subject = clean_subject(commit['subject'])
            pr_num = get_pr_number(commit['subject'])
            author = commit['github_author']
            parts = [f'- {subject}']
            if pr_num:
                parts.append(f'([#{pr_num}]({repo_url}/pull/{pr_num}))')
            else:
                parts.append(f"([`{commit['short_sha']}`]({repo_url}/commit/{commit['sha']}))")
            if author not in teknium_aliases:
                parts.append(f'— {author}')
            lines.append(' '.join(parts))
        lines.append('')
    if all_authors:
        author_counts = defaultdict(int)
        for commit in commits:
            author = commit['github_author']
            if author not in teknium_aliases:
                author_counts[author] += 1
            for coauthor in commit.get('coauthors', []):
                if coauthor not in teknium_aliases:
                    author_counts[coauthor] += 1
        sorted_authors = sorted(author_counts.items(), key=lambda x: -x[1])
        lines.append('## 👥 Contributors')
        lines.append('')
        lines.append('Thank you to everyone who contributed to this release!')
        lines.append('')
        for author, count in sorted_authors:
            commit_word = 'commit' if count == 1 else 'commits'
            lines.append(f'- {author} ({count} {commit_word})')
        lines.append('')
    if prev_tag:
        lines.append(f'**Full Changelog**: [{prev_tag}...{tag_name}]({repo_url}/compare/{prev_tag}...{tag_name})')
    else:
        lines.append(f'**Full Changelog**: [{tag_name}]({repo_url}/commits/{tag_name})')
    lines.append('')
    return '\n'.join(lines)

def main():
    parser = argparse.ArgumentParser(description='Duck Agent Release Tool')
    parser.add_argument('--bump', choices=['major', 'minor', 'patch'], help='Which semver component to bump')
    parser.add_argument('--publish', action='store_true', help='Actually create the tag and GitHub release (otherwise dry run)')
    parser.add_argument('--date', type=str, help='Override CalVer date (format: YYYY.M.D)')
    parser.add_argument('--first-release', action='store_true', help='Mark as first release (no previous tag expected)')
    parser.add_argument('--output', type=str, help='Write changelog to file instead of stdout')
    args = parser.parse_args()
    if args.date:
        calver_date = args.date
    else:
        now = datetime.now()
        calver_date = f'{now.year}.{now.month}.{now.day}'
    base_tag = f'v{calver_date}'
    tag_name, calver_date = next_available_tag(base_tag)
    if tag_name != base_tag:
        print(f'Note: Tag {base_tag} already exists, using {tag_name}')
    current_version = get_current_version()
    if args.bump:
        new_version = bump_version(current_version, args.bump)
    else:
        new_version = current_version
    prev_tag = get_last_tag()
    if not prev_tag and (not args.first_release):
        print('No previous tags found. Use --first-release for the initial release.')
        print(f'Would create tag: {tag_name}')
        print(f'Would set version: {new_version}')
        return
    commits = get_commits(since_tag=prev_tag)
    if not commits:
        print('No new commits since last tag.')
        if not args.first_release:
            return
    print(f"{'=' * 60}")
    print('  Duck Agent Release Preview')
    print(f"{'=' * 60}")
    print(f'  CalVer tag:      {tag_name}')
    print(f'  SemVer:          v{current_version} → v{new_version}')
    print(f"  Previous tag:    {prev_tag or '(none — first release)'}")
    print(f'  Commits:         {len(commits)}')
    print(f"  Unique authors:  {len({c['github_author'] for c in commits})}")
    print(f"  Mode:            {('PUBLISH' if args.publish else 'DRY RUN')}")
    print(f"{'=' * 60}")
    print()
    changelog = generate_changelog(commits, tag_name, new_version, prev_tag=prev_tag, first_release=args.first_release)
    if args.output:
        Path(args.output).write_text(changelog, encoding='utf-8')
        print(f'Changelog written to {args.output}')
    else:
        print(changelog)
    if args.publish:
        print(f"\n{'=' * 60}")
        print('  Publishing release...')
        print(f"{'=' * 60}")
        if args.bump:
            update_version_files(new_version, calver_date)
            print(f'  ✓ Updated version files to v{new_version} ({calver_date})')
            add_files = [str(VERSION_FILE), str(PYPROJECT_FILE)]
            add_result = git_result('add', *add_files)
            if add_result.returncode != 0:
                print(f'  ✗ Failed to stage version files: {add_result.stderr.strip()}')
                return
            commit_result = git_result('commit', '-m', f'chore: bump version to v{new_version} ({calver_date})')
            if commit_result.returncode != 0:
                print(f'  ✗ Failed to commit version bump: {commit_result.stderr.strip()}')
                return
            print('  ✓ Committed version bump')
        tag_result = git_result('tag', '-a', tag_name, '-m', f'Duck Agent v{new_version} ({calver_date})\n\nWeekly release')
        if tag_result.returncode != 0:
            print(f'  ✗ Failed to create tag {tag_name}: {tag_result.stderr.strip()}')
            return
        print(f'  ✓ Created tag {tag_name}')
        push_result = git_result('push', 'origin', 'HEAD', '--tags')
        if push_result.returncode == 0:
            print('  ✓ Pushed to origin')
        else:
            print(f'  ✗ Failed to push to origin: {push_result.stderr.strip()}')
            print('    Continue manually after fixing access:')
            print('    git push origin HEAD --tags')
        changelog_file = REPO_ROOT / '.release_notes.md'
        changelog_file.write_text(changelog, encoding='utf-8')
        gh_cmd = ['gh', 'release', 'create', tag_name, '--title', f'Duck Agent v{new_version} ({calver_date})', '--notes-file', str(changelog_file)]
        gh_bin = shutil.which('gh')
        if gh_bin:
            result = subprocess.run(gh_cmd, capture_output=True, text=True, encoding='utf-8', errors='replace', cwd=str(REPO_ROOT))
        else:
            result = None
        if result and result.returncode == 0:
            changelog_file.unlink(missing_ok=True)
            print(f'  ✓ GitHub release created: {result.stdout.strip()}')
            print(f'\n  🎉 Release v{new_version} ({tag_name}) published!')
        else:
            if result is None:
                print('  ✗ GitHub release skipped: `gh` CLI not found.')
            else:
                print(f'  ✗ GitHub release failed: {result.stderr.strip()}')
            print(f'    Release notes kept at: {changelog_file}')
            print('    Tag was created locally. Create the release manually:')
            print(f"    gh release create {tag_name} --title 'Duck Agent v{new_version} ({calver_date})' --notes-file .release_notes.md")
            print(f'\n  ✓ Release v{new_version} ({tag_name}) prepared for manual publish.')
    else:
        print(f"\n{'=' * 60}")
        print('  Dry run complete. To publish, add --publish')
        print('  Example: python scripts/release.py --bump minor --publish')
        print(f"{'=' * 60}")
if __name__ == '__main__':
    main()